final class CatalogRouteRegistrar { public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){} public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$transactions=new DoctrineTransactionManager($em);$positions=new DoctrinePositionRepository($em);$syllabi=new DoctrineSyllabusRepository($em);$identity=new IdentityRequestFactory();$requests=new PositionSyllabusRequestFactory();$controller=new PositionSyllabusController($this->auth,new CreatePositionService(new DoctrineExamRepository($em),$positions,new PositionResponseMapper(),$transactions),new ListPositionsService($positions,new PositionResponseMapper()),new CreateSyllabusService(new DoctrineExamRepository($em),$syllabi,new SyllabusResponseMapper(),$transactions),new ListSyllabiService($syllabi,new SyllabusResponseMapper()),$this->responses);$documents=new SyllabusDocumentController($this->auth,new UploadSyllabusDocumentService($syllabi,new LocalSyllabusDocumentStorage(Database::env('SYLLABUS_DOCUMENT_DIRECTORY','/app/storage/syllabi')),$transactions),$this->responses);$processing=new SyllabusProcessingController($this->auth,new QueueSyllabusProcessingService($syllabi,new DoctrineSyllabusProcessingJobRepository($em),new SyllabusProcessingJobResponseMapper(),$transactions),new ListSyllabusDocumentExtractionsService(new DoctrineSyllabusDocumentExtractionRepository($em),new SyllabusDocumentExtractionResponseMapper()),$this->responses);$processingRequests=new SyllabusProcessingRequestFactory();$responses=$this->responses;$app->get('/v1/exams/{examId}/positions',static fn(ServerRequestInterface $request,ResponseInterface $response,array $args):ResponseInterface=>$controller->listPositions($request,$response,$identity->accessToken($request),(string)$args['examId']));$app->post('/v1/exams/{examId}/positions',static function(ServerRequestInterface $request,ResponseInterface $response,array $args)use($controller,$requests,$identity,$responses):