response,array $args):ResponseInterface=>$processing->latest($request,$response,$identity->accessToken($request),(string)$args['id']));$app->get('/v1/admin/syllabi/{id}/extractions',static fn(ServerRequestInterface $request,ResponseInterface $response,array $args):ResponseInterface=>$processing->listExtractions($request,$response,$identity->accessToken($request),(string)$args['id']));} }
